INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63463762', 63463762, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB PURWAKARTA', 'Biaya Jasa Manajemen Building', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Purwakarta (Kab.)', 126462000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Paket, @ 126462000 )', '1. Biaya Jasa Manajemen Building ( 1, Paket, @ 126462000 );', 'A. Perusahaan Penyedia Jasa Outsourcing: 1. Memiliki ijin usaha dibidang outsourcing; 2. Memiliki pengalaman mengelola outsourcing minimal 3 tahun; 3. Taat pajak/ telah membayar dan melaporkan pajak tahun terakhir, dibuktikan dengan laporan SPT 2022; 4. Memiliki NPWP; 5. Memiliki pengalaman pengadaan outsourcing di tingkat nasional lebih diutamakan; B. Anggota Keamanan; 1. Jumlah 4 (empat) orang Pria; 2. Usia maksimal 55 Tahun (copy KTP); 3. Pendidikan minimal SMA/Sederajat (copy ijazah); 4. Memiliki Sertifikat Gada Pratama (copy sertifikat) bagi tenaga keamanan baru. Bagi tenaga keamanan eksisting yang belum memiliki sertifikat Gada Pratama akan diberikan waktu selama 3 (tiga) bulan untuk melengkapai persyaratan sertifikat Gada Pratama; 5. Memiliki pengalaman kerja minimal 1 tahun dibidang tenaga keamanan; 6. Berpenampilan menarik; 7. Tinggi badan minimal 160 cm bagi Pria dan minimal 155 cm bagi Wanita; 8. Memiliki surat keterangan sehat dari dokter yang masih berlaku; 9. Tidak memiliki Tatoo/bekas Tatoo pada bagian tubuh yang terlihat dan tidak bertindik; C. Petugas Kebersihan; 1. Jumlah 1 (satu) orang Pria; 2. Usia maksimal 55 Tahun (copy KTP); 3. Pendidikan minimal SMA/Sederajat (copy ijazah); 4. Memiliki pengalaman kerja minimal 1 tahun dibidang tenaga kebersihan; 5. Berpenampilan menarik; 6. Memiliki surat keterangan sehat dari dokter yang masih berlaku; 7. Tidak memiliki Tatoo/bekas Tatoo pada bagian tubuh yang terlihat dan tidak bertindik; Catatan : Syarat No. B.8 dan C.6 harus dipenuhi setelah penyedia terpilih menjadi pemenang dan wajib menyampaikan personil pengganti jika dinyatakan tidak memenuhi syarat. D. Anggota Keamanan dan petugas kebersihan mempunyai tugas dan tanggung jawab mengamankan, membersihkan dan menertibkan seluruh aset bangunan dan fasilitas pendukung yang berada di lingkungan kantor BPS Kabupaten Purwakarta, dengan data bangunan gedung sebagai berikut: 1. Lokasi Kantor BPS Kabupaten Purwakarta : Jalan Syeikh Baing Yusuf, Maracang RT 031/009, Babakancikao, Purwakarta, Jawa Barat 2. Gedung Kantor BPS Kabupaten Purwakarta terdiri dari 1 lantai 3. Halaman parkir kendaraan terdiri dari area parkir roda 4 dan parkir roda 2 4. Fasilitas pendukung berupa aula dan mushola.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 973489);
